SELECT /* LGVPAY00035.retrievePayrollRunEmpList */ pcee.payroll_calculation_exec_id , pcee.employee_no AS employee_no , em.full_name_local AS employee_name , em.org_name_local AS organization_name , TO_CHAR(em.date_hire_subsidiary,'dd/mm/yyyy') AS hire_date , TO_CHAR(em.date_retire,'dd/mm/yyyy') AS resignation_date , NVL(pcee.error_flag, 'N') AS error_flag FROM tb_pay_calc_emp_exec_n pcee , emp_master em WHERE pcee.payroll_calculation_exec_id = #{payrollCalculationExecId, jdbcType=NUMERIC}
AND pcee.employee_no = #{detailEmployeeNo}
AND em.employee_number = pcee.employee_no AND EXISTS ( SELECT 1 FROM tb_pay_calc_exec_n pce WHERE pce.payroll_calculation_exec_id = pcee.payroll_calculation_exec_id AND pce.payroll_type_code = 'MTH_OS' ) /* LGVPAY00035 : MTH_OS 전용 */ ORDER BY NVL(pcee.error_flag, 'N') DESC, pcee.employee_no
